def read_status():
    """Doc."""
    cmd = f"{STATION_ID:02X}03{0x30:04X}0001"
    full_cmd = cmd + modbus_crc(cmd)
    resp = send_raw(full_cmd)
    
    if resp and len(resp) >= 10 and resp.startswith(f"{STATION_ID:02X}03"):
        data_hex = resp[6:10]
        status = int(data_hex, 16)
        status_swapped = swap_bytes(status)
        return status_swapped
    return None

def is_test_complete():
    """Doc."""
    step = read_step_code()
    return step == 0

def wait_for_test_complete(timeout=120, poll_interval=0.5):
    """Doc."""
    start_time = time.time()
    while time.time() - start_time < timeout:
        if is_test_complete():
            return True
        time.sleep(poll_interval)
    return False

def start_test():
    """Doc."""
    cmd = f"{STATION_ID:02X}05{0x01:04X}FF00"
    full_cmd = cmd + modbus_crc(cmd)
    resp = send_raw(full_cmd)
    time.sleep(0.1)
    off_cmd = f"{STATION_ID:02X}05{0x01:04X}0000"
    send_raw(off_cmd + modbus_crc(off_cmd))
    return resp is not None and resp.startswith(f"{STATION_ID:02X}05")

def reset_device():
    """Doc."""
    cmd = f"{STATION_ID:02X}05{0x00:04X}FF00"
    full_cmd = cmd + modbus_crc(cmd)
    resp = send_raw(full_cmd)
    return resp is not None and resp.startswith(f"{STATION_ID:02X}05")

