    def execute_async(self, program1, program2=0, switch_chamber=False, test_info=None):
        """Doc."""
        with self._execution_lock:
            if self.running or self.hw_running or (self.test_thread and self.test_thread.is_alive()):
                return False, "Test already running"

            # The current scan is being handled by the Modbus sequence. Mark its
            # hardware token consumed so the background IO monitor cannot replay it.
            self._hw_consumed_generation = self._hw_context_generation
            self.running = True
            self.active_slot = 1
            try:
                if test_info:
                    self.set_test_info(
                        test_info.get('product_model', ''),
                        test_info.get('operator', ''),
                        test_info.get('qr_code', ''),
                        test_info.get('label_template', ''),
                        test_info.get('supplier_code', ''),
                    )
                self.test_thread = threading.Thread(
                    target=self.execute_test_sequence,
                    args=(program1, program2, bool(switch_chamber))
                )
                self.test_thread.daemon = True
                self.test_thread.start()
            except Exception:
                self.running = False
                raise
            return True, "Test started"

    def _plc_command_monitor(self):
        """Map PLC M25.0/M25.1 rising edges to the UI start/stop actions."""
        from line_runtime import get_line_settings, logger as plc_logger, read_plc_control_inputs

        previous_start = False
        previous_stop = False
        initialized = False
        last_error = ""
        last_error_at = 0.0
        poll_interval = max(0.05, float(os.environ.get("PLC_CONTROL_POLL_SECONDS", "0.10")))

        while True:
            try:
                inputs = read_plc_control_inputs()
                start_signal = bool(inputs.get("start"))
                stop_signal = bool(inputs.get("stop"))

                if initialized:
                    stop_rising = stop_signal and not previous_stop
                    start_rising = start_signal and not previous_start

                    if stop_rising:
                        print("[PLC-CONTROL] M25.1 rising edge: execute UI stop action")
                        plc_logger.info("M25.1 rising edge: execute UI stop action")
                        self.stop()
                    elif start_rising:
                        ctx = dict(self._hw_monitor_pending_context or {})
                        try:
                            program1 = int(ctx.get("program1") or 0)
                            program2 = int(ctx.get("program2") or 0)
                        except Exception:
                            program1 = 0
                            program2 = 0
                        switch_chamber = bool(ctx.get("switch_chamber")) and program2 > 0
                        qr_code = str(ctx.get("qr_code") or "").strip()
                        settings = get_line_settings()

                        if program1 <= 0:
                            print("[PLC-CONTROL] M25.0 ignored: no valid program1 context")
                        elif settings.get("scan_required", True) and not qr_code:
                            print("[PLC-CONTROL] M25.0 ignored: scan is required but QR context is empty")
                        else:
                            test_info = {
                                "product_model": ctx.get("product_model") or "",
                                "operator": ctx.get("operator") or "",
                                "qr_code": qr_code,
                                "label_template": ctx.get("label_template") or "",
                                "supplier_code": ctx.get("supplier_code") or "",
                            }
                            ok, message = self.execute_async(
                                program1,
                                program2 if switch_chamber else 0,
                                switch_chamber,
                                test_info,
                            )
                            print(
                                f"[PLC-CONTROL] M25.0 rising edge: UI start action "
                                f"success={ok}, message={message}, program1={program1}, "
                                f"program2={program2 if switch_chamber else 0}"
                            )
                            plc_logger.info(
                                "M25.0 rising edge: UI start action success=%s, message=%s, program1=%s, program2=%s",
                                ok,
                                message,
                                program1,
                                program2 if switch_chamber else 0,
                            )

                previous_start = start_signal
                previous_stop = stop_signal
                initialized = True
                last_error = ""
                last_error_at = 0.0
            except Exception as exc:
                message = str(exc)
                now = time.time()
                if message != last_error or now - last_error_at >= 30.0:
                    print(f"[PLC-CONTROL] M25 input read failed: {message}")
                    plc_logger.warning("M25 input read failed: %s", message)
                    last_error = message
                    last_error_at = now
            time.sleep(poll_interval)
    
    def _hw_stepcode_monitor(self):
        """Background thread: watch stepcode independently of UI Start."""
        cycle_detector = StepCodeCycleDetector()
        prev_stepcode = 0
        cycle_active = False
        in_step6 = False
        hw_slot = 1
        program2_start_requested_at = 0.0
        program2_pulse_attempts = 0
        pressure_at_6 = None
        leak_at_6 = None
        pressure_at_active = None
        leak_at_active = None
        pressure_at_65535 = None
        leak_at_65535 = None
        poll_interval = 0.3

        def reset_capture():
            nonlocal in_step6, pressure_at_6, leak_at_6
            nonlocal pressure_at_active, leak_at_active, pressure_at_65535, leak_at_65535
            in_step6 = False
            pressure_at_6 = None
            leak_at_6 = None
            pressure_at_active = None
            leak_at_active = None
            pressure_at_65535 = None
            leak_at_65535 = None

        def clear_test_data_for_hardware_cycle():
            self.active_slot = 1
            self.test_data['program1'] = None
            self.test_data['program2'] = None
            self.test_data['pressure1'] = None
            self.test_data['leak1'] = None
            self.test_data['pressure1_unit'] = None
            self.test_data['leak1_unit'] = None
            self.test_data['result1'] = None
            self.test_data['pressure2'] = None
            self.test_data['leak2'] = None
            self.test_data['pressure2_unit'] = None
            self.test_data['leak2_unit'] = None
            self.test_data['result2'] = None
            self.test_data['program1_pass'] = False
            self.test_data['program2_pass'] = False
            self.completion_payload = None
            self.record_saved_payload = None

        def apply_pending_context():
            ctx = self._hw_monitor_pending_context or {}
            if ctx.get("product_model"):
                self.product_model = ctx["product_model"]
            if ctx.get("operator"):
                self.operator = ctx["operator"]
            if "qr_code" in ctx:
                self.qr_code = ctx["qr_code"]
            if ctx.get("label_template"):
                self.label_template = ctx["label_template"]
            if ctx.get("supplier_code"):
                self.supplier_code = ctx["supplier_code"]
            return ctx

        def should_run_program2(ctx):
            # Passive StepCode monitoring never issues a second start command.
            # A second chamber remains available through the operator Start flow.
            return False

        def assign_result(slot, data):
            nonlocal pressure_at_65535, leak_at_65535
            if data:
                pressure_at_65535 = data.get('pressure')
                leak_at_65535 = data.get('leak')
            fp = pressure_at_active if pressure_at_active is not None else (pressure_at_6 if pressure_at_6 is not None else 0)
            fl = leak_at_65535 if leak_at_65535 is not None else (leak_at_active if leak_at_active is not None else (leak_at_6 if leak_at_6 is not None else 0))
            fr = data.get('test_result', 'UNKNOWN') if data else 'UNKNOWN'
            pressure_unit = data.get('pressure_unit') if data else None
            leak_unit = data.get('leak_unit') if data else None

            if slot == 2:
                self.test_data.update({
                    'pressure2': fp,
                    'leak2': fl,
                    'pressure2_unit': pressure_unit,
                    'leak2_unit': leak_unit,
                    'result2': fr,
                    'program2_pass': fr == 'PASS',
                })
            else:
                ctx = self._hw_monitor_pending_context or {}
                self.test_data.update({
                    'program1': int(ctx.get("program1") or 0) or None,
                    'pressure1': fp,
                    'leak1': fl,
                    'pressure1_unit': pressure_unit,
                    'leak1_unit': leak_unit,
                    'result1': fr,
                    'program1_pass': fr == 'PASS',
                })
            print(
                f"[HW-MONITOR] program{slot} result snapshot: "
                f"pressure={fp} {pressure_unit}, leak={fl} {leak_unit}, result={fr}"
            )

        def collect_completion_data(stepcode):
            data = None
            for _ in range(3):
                data = self.collect_test_data()
                if data:
                    break
                time.sleep(0.05)

            if data and stepcode == 65535:
                capture_deadline = time.time() + 1.0
                while time.time() < capture_deadline:
                    time.sleep(0.05)
                    if read_step_code() != 65535:
                        break
                    latest_data = self.collect_test_data()
                    if latest_data:
                        data = latest_data
            return data

        def start_program2_with_plc(ctx):
            nonlocal program2_start_requested_at, program2_pulse_attempts
            program2 = int(ctx.get("program2") or 0)
            self.update_status('waiting', 'Waiting 2 seconds before hardware program 2 start', 2)
            try:
                from line_runtime import set_m26_0
                set_m26_0(False)
            except Exception as exc:
                print(f"[HW-MONITOR] M26.0 OFF before program2 failed: {exc}")

            ok, msg = write_program(program2)
            if not ok:
                raise RuntimeError(f"Program 2 selection failed: {msg}")
            current = read_current_program()
            if current != program2:
                raise RuntimeError(f"Program 2 selection verify failed: expected {program2}, actual {current}")

            self.test_data['program2'] = program2
            self.update_status('select_program2', f'Program 2 selected: {program2}', 2)
            self._persist_runtime_state()
            time.sleep(2.0)

            from line_runtime import set_m26_0
            set_m26_0(True)
            program2_start_requested_at = time.time()
            program2_pulse_attempts = 1
            self.update_status('running_program2', 'Program 2 started by PLC M26.0', 2)
            print(f"[HW-MONITOR] Program 2 hardware start pulsed through M26.0, program2={program2}")

        def retry_program2_plc_start():
            nonlocal program2_start_requested_at, program2_pulse_attempts
            if program2_pulse_attempts >= 3:
                raise RuntimeError("Program 2 did not start after 3 M26.0 pulses")
            from line_runtime import set_m26_0
            set_m26_0(False)
            time.sleep(0.3)
            set_m26_0(True)
            program2_pulse_attempts += 1
            program2_start_requested_at = time.time()
            print(f"[HW-MONITOR] Retried program 2 M26.0 pulse, attempt={program2_pulse_attempts}")

        if self.current_phase == 'running_program2' and self.test_data.get('program2') and not self.test_data.get('result2'):
            hw_slot = 2
            self.hw_running = True
            program2_start_requested_at = time.time()
            program2_pulse_attempts = 1

        while True:
            try:
                time.sleep(poll_interval)
                if self.running:
                    cycle_detector.observe(None)
                    prev_stepcode = 0
                    cycle_active = False
                    hw_slot = 1
                    self.hw_running = False
                    reset_capture()
                    continue
                sc = read_step_code()
                if sc is None:
                    cycle_detector.observe(None)
                    continue
                cycle_started = cycle_detector.observe(sc)
                if sc >= 4 and sc <= 100:
                    if not cycle_active:
                        if not cycle_started:
                            prev_stepcode = sc
                            continue
                        cycle_active = True
                        reset_capture()
                        self.hw_running = True
                        if hw_slot == 1:
                            self._hw_consumed_generation = self._hw_context_generation
                            clear_test_data_for_hardware_cycle()
                            ctx = apply_pending_context()
                            try:
                                self.test_data['program1'] = int(ctx.get("program1") or 0) or None
                            except Exception:
                                self.test_data['program1'] = None
                            self.update_status('running_program1', 'ATEQ test detected at StepCode 4', 1)
                        else:
                            self.update_status('running_program2', 'ATEQ program 2 detected at StepCode 4', 2)
                            program2_start_requested_at = 0.0
                        self._persist_runtime_state()
                        print(f"[HW-MONITOR] External program{hw_slot} cycle started, stepcode={sc}")
                    active_data = None
                    if sc >= 4 and sc <= 6:
                        active_data = self.collect_test_data()
                        if active_data:
                            pressure_at_active = active_data["pressure"]
                            leak_at_active = active_data["leak"]

                    if sc == 6:
                        if not in_step6:
                            in_step6 = True
                            print("[HW-MONITOR] Enter stepcode=6")
                        data = active_data or self.collect_test_data()
                        if data:
                            pressure_at_6 = data["pressure"]
                            leak_at_6 = data["leak"]
                    else:
                        if in_step6:
                            print(f"[HW-MONITOR] Exit stepcode=6, pressure={pressure_at_6}, leak={leak_at_6}")
                            in_step6 = False
                elif cycle_active and sc in (0, 65535):
                    print(f"[HW-MONITOR] External program{hw_slot} cycle complete, stepcode={sc}")
                    data = collect_completion_data(sc)
                    assign_result(hw_slot, data)
                    cycle_active = False
                    reset_capture()

                    ctx = self._hw_monitor_pending_context or {}
                    if hw_slot == 1 and should_run_program2(ctx):
                        self.update_status('program1_complete', 'Program 1 complete, preparing program 2', 1)
                        try:
                            start_program2_with_plc(ctx)
                            hw_slot = 2
                        except Exception as exc:
                            print(f"[HW-MONITOR] Program 2 hardware sequence failed: {exc}")
                            self.current_phase = 'error'
                            self.completion_payload = {
                                'program1': self.test_data.get('program1'),
                                'program2': self.test_data.get('program2'),
                                'pressure1': self.test_data.get('pressure1'),
                                'leak1': self.test_data.get('leak1'),
                                'pressure1_unit': self.test_data.get('pressure1_unit'),
                                'leak1_unit': self.test_data.get('leak1_unit'),
                                'result1': self.test_data.get('result1'),
                                'program1_pass': self.test_data.get('program1_pass', False),
                                'pressure2': self.test_data.get('pressure2'),
                                'leak2': self.test_data.get('leak2'),
                                'pressure2_unit': self.test_data.get('pressure2_unit'),
                                'leak2_unit': self.test_data.get('leak2_unit'),
                                'result2': self.test_data.get('result2'),
                                'program2_pass': self.test_data.get('program2_pass', False),
                                'overall_result': 'FAIL',
                                'qr_code': self.qr_code,
                                'record_saved': False,
                                'phase': 'error',
                                'error': str(exc),
                            }
                            self.completion_sequence += 1
                            self.hw_running = False
                            hw_slot = 1
                            program2_start_requested_at = 0.0
                            self._persist_runtime_state()
                    else:
                        if hw_slot == 2:
                            self.update_status('program2_complete', 'Program 2 complete', 2)
                        else:
                            self.update_status('complete', 'Hardware test complete', hw_slot)
                        self.hw_running = False
                        self.save_test_record_to_database()
                        hw_slot = 1
                        program2_start_requested_at = 0.0
                elif (
                    not cycle_active
                    and hw_slot == 2
                    and program2_start_requested_at > 0
                    and sc in (0, 65535)
                    and (time.time() - program2_start_requested_at) >= 3.0
                ):
                    try:
                        retry_program2_plc_start()
                    except Exception as exc:
                        print(f"[HW-MONITOR] Program 2 start watchdog failed: {exc}")
                        try:
                            from line_runtime import set_m26_0
                            set_m26_0(False)
                        except Exception:
                            pass
                        self.current_phase = 'error'
                        self.hw_running = False
                        hw_slot = 1
                        program2_start_requested_at = 0.0
                        self.completion_payload = {
                            'program1': self.test_data.get('program1'),
                            'program2': self.test_data.get('program2'),
                            'pressure1': self.test_data.get('pressure1'),
                            'leak1': self.test_data.get('leak1'),
                            'pressure1_unit': self.test_data.get('pressure1_unit'),
                            'leak1_unit': self.test_data.get('leak1_unit'),
                            'result1': self.test_data.get('result1'),
                            'program1_pass': self.test_data.get('program1_pass', False),
                            'pressure2': self.test_data.get('pressure2'),
                            'leak2': self.test_data.get('leak2'),
                            'pressure2_unit': self.test_data.get('pressure2_unit'),
                            'leak2_unit': self.test_data.get('leak2_unit'),
                            'result2': self.test_data.get('result2'),
                            'program2_pass': self.test_data.get('program2_pass', False),
                            'overall_result': 'FAIL',
                            'qr_code': self.qr_code,
                            'record_saved': False,
                            'phase': 'error',
                            'error': str(exc),
                        }
                        self.completion_sequence += 1
                        self._persist_runtime_state()
                prev_stepcode = sc
            except Exception as e:
                print(f"[HW-MONITOR] Error: {e}")
                self.hw_running = False
                self._persist_runtime_state()
                time.sleep(1)

    def set_pending_test_context(self, product_model=None, operator=None, qr_code=None, label_template=None, supplier_code='', program1=None, program2=None, switch_chamber=False, arm_hardware_cycle=False):
        """Store pending context for hardware-triggered tests."""
        self._hw_monitor_pending_context = {
            'product_model': product_model or self.product_model,
            'operator': operator or self.operator,
            'qr_code': self.qr_code if qr_code is None else qr_code,
            'label_template': label_template or self.label_template,
            'supplier_code': supplier_code or self.supplier_code,
            'program1': program1,
            'program2': program2,
            'switch_chamber': bool(switch_chamber),
        }
        if arm_hardware_cycle:
            self._hw_context_generation += 1
        print(
            f"[HW-MONITOR] Context updated: product={self._hw_monitor_pending_context.get('product_model')}, "
            f"qr={self._hw_monitor_pending_context.get('qr_code')}, program1={program1}, "
            f"program2={program2}, switch_chamber={bool(switch_chamber)}, "
            f"generation={self._hw_context_generation}, armed={bool(arm_hardware_cycle)}"
        )

    def stop(self):
        """Doc."""
        self.running = False
        reset_device()
        self.update_status('stopped', 'Test stopped')
        self._persist_runtime_state()

